    getAgentDID(doc) {
        if (doc.didDocumentRegistration?.type !== 'agent') {
            throw new KeymasterError('Document is not an agent');
        }
        const did = doc.didDocument?.id;
        if (!did) {
            throw new KeymasterError('Agent document does not have a DID');
        }
        return did;
    }
    async addVaultMember(vaultId, memberId) {
        const owner = await this.checkVaultOwner(vaultId);
        const idKeypair = await this.fetchKeyPair();
        const vault = await this.getVault(vaultId);
        const { privateJwk, config, members } = await this.decryptVault(vault);
        const memberDoc = await this.resolveDID(memberId, { confirm: true });
        const memberDID = this.getAgentDID(memberDoc);
        // Don't allow adding the vault owner
        if (owner === memberDID) {
            return false;
        }
        members[memberDID] = { added: new Date().toISOString() };
        const publicJwk = config.secretMembers ? idKeypair.publicJwk : vault.publicJwk;
        vault.members = this.cipher.encryptMessage(publicJwk, JSON.stringify(members));
        await this.addMemberKey(vault, memberDID, privateJwk);
        return this.mergeData(vaultId, { vault });
    }
    async removeVaultMember(vaultId, memberId) {
        const owner = await this.checkVaultOwner(vaultId);
        const idKeypair = await this.fetchKeyPair();
        const vault = await this.getVault(vaultId);
        const { config, members } = await this.decryptVault(vault);
        const memberDoc = await this.resolveDID(memberId, { confirm: true });
        const memberDID = this.getAgentDID(memberDoc);
        // Don't allow removing the vault owner
        if (owner === memberDID) {
            return false;
        }
        delete members[memberDID];
        const publicJwk = config.secretMembers ? idKeypair.publicJwk : vault.publicJwk;
        vault.members = this.cipher.encryptMessage(publicJwk, JSON.stringify(members));
        const memberKeyId = this.generateSaltedId(vault, memberDID);
        delete vault.keys[memberKeyId];
        return this.mergeData(vaultId, { vault });
    }
    async listVaultMembers(vaultId) {
        const vault = await this.getVault(vaultId);
        const { members, isOwner } = await this.decryptVault(vault);
        if (isOwner) {
            await this.checkVaultVersion(vaultId, vault);
        }
        return members;
    }
    async addVaultItem(vaultId, name, buffer) {
        await this.checkVaultOwner(vaultId);
        const vault = await this.getVault(vaultId);
        const { items } = await this.decryptVault(vault);
        const validName = this.validateAlias(name);
        const encryptedData = this.cipher.encryptBytes(vault.publicJwk, buffer);
        const cid = await this.gatekeeper.addText(encryptedData);
        const sha256 = this.cipher.hashMessage(buffer);
        const type = await this.getMimeType(buffer);
        const data = encryptedData.length < this.maxDataLength ? encryptedData : undefined;
        items[validName] = {
            cid,
            sha256,
            bytes: buffer.length,
            type,
            added: new Date().toISOString(),
            data,
        };
        vault.items = this.cipher.encryptMessage(vault.publicJwk, JSON.stringify(items));
        vault.sha256 = this.cipher.hashJSON(items);
        return this.mergeData(vaultId, { vault });
    }
    async removeVaultItem(vaultId, name) {
        await this.checkVaultOwner(vaultId);
        const vault = await this.getVault(vaultId);
        const { items } = await this.decryptVault(vault);
        delete items[name];
        vault.items = this.cipher.encryptMessage(vault.publicJwk, JSON.stringify(items));
        vault.sha256 = this.cipher.hashJSON(items);
        return this.mergeData(vaultId, { vault });
    }
    async listVaultItems(vaultId, options) {
        const vault = await this.getVault(vaultId, options);
        const { items } = await this.decryptVault(vault);
        return items;
    }
    async getVaultItem(vaultId, name, options) {
        const vault = await this.getVault(vaultId, options);
        const { privateJwk, items } = await this.decryptVault(vault);
        if (!items[name]) {
            return null;
        }
        const encryptedData = items[name].data || await this.gatekeeper.getText(items[name].cid);
        if (!encryptedData) {
            throw new KeymasterError(`Failed to retrieve data for item '${name}' (CID: ${items[name].cid})`);
        }
        const bytes = this.cipher.decryptBytes(privateJwk, encryptedData, vault.publicJwk);
        return Buffer.from(bytes);
    }
    async listDmail() {
        const wallet = await this.loadWallet();
        const id = await this.fetchIdInfo(undefined, wallet);
        const list = id.dmail || {};
        const dmailList = {};
        const nameList = await this.listAliases({ includeIDs: true });
        const didToName = Object.entries(nameList).reduce((acc, [name, did]) => {
            acc[did] = name;
            return acc;
        }, {});
        for (const did of Object.keys(list)) {
            const message = await this.getDmailMessage(did);
            if (!message) {
                continue; // Skip if no dmail found for this DID
            }
            const tags = list[did].tags ?? [];
            const docs = await this.resolveDID(did);
            const controller = docs.didDocument?.controller ?? '';
            const sender = didToName[controller] ?? controller;
            const date = docs.didDocumentMetadata?.updated ?? '';
            const to = message.to.map(did => didToName[did] ?? did);
            const cc = message.cc.map(did => didToName[did] ?? did);
            const attachments = await this.listDmailAttachments(did);
            dmailList[did] = {
                message,
                to,
                cc,
                tags,
                sender,
                date,
                attachments,
                docs,
            };
        }
        return dmailList;
    }
    verifyTagList(tags) {
        if (!Array.isArray(tags)) {
            throw new InvalidParameterError('tags');
        }
        const tagSet = new Set();
        for (const tag of tags) {
            try {
                tagSet.add(this.validateAlias(tag));
            }
            catch (error) {
                throw new InvalidParameterError(`Invalid tag: '${tag}'`);
            }
        }
        return tagSet.size > 0 ? Array.from(tagSet) : [];
    }
    async fileDmail(did, tags) {
        const verifiedTags = this.verifyTagList(tags);
        await this.mutateWallet(async (wallet) => {
            const id = await this.fetchIdInfo(undefined, wallet);
            if (!id.dmail) {
                id.dmail = {};
            }
            id.dmail[did] = { tags: verifiedTags };
        });
        return true;
    }
    async removeDmail(did) {
        await this.mutateWallet(async (wallet) => {
            const id = await this.fetchIdInfo(undefined, wallet);
            if (!id.dmail || !id.dmail[did]) {
                return;
            }
            delete id.dmail[did];
        });
        return true;
    }
